import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.shared .align 4 .f32 As[1024];
.shared .align 4 .f32 Bs[1024];
.visible .entry triu_matmul_kernel(
    .param .u64 _A,
    .param .u64 _B,
    .param .u64 _C,
    .param .u32 _N
)
{
    .reg .pred %p<32>;
    .reg .b32 %r<128>;
    .reg .b64 %rd<128>;
    .reg .f32 %f<128>;

    ld.param.u64 %rd0, [_A];
    ld.param.u64 %rd1, [_B];
    ld.param.u64 %rd2, [_C];
    ld.param.u32 %r0, [_N];

    mov.u32 %r1, %ctaid.x;        // col block
    mov.u32 %r2, %ctaid.y;        // row block
    mov.u32 %r3, %tid.x;          // tx in [0,16)
    mov.u32 %r4, %tid.y;          // ty in [0,16)

    shl.b32 %r5, %r2, 5;          // row0 = by*32
    shl.b32 %r6, %r1, 5;          // col0 = bx*32
    add.u32 %r9, %r5, %r4;        // A row 0
    add.u32 %r10, %r9, 16;        // A row 1
    add.u32 %r11, %r6, %r3;       // B col 0 / C col 0
    add.u32 %r12, %r11, 16;       // B col 1 / C col 1

    mov.f32 %f0, 0f00000000;
    mov.f32 %f1, 0f00000000;
    mov.f32 %f2, 0f00000000;
    mov.f32 %f3, 0f00000000;
    mov.f32 %f30, 0f00000000;

    mov.u64 %rd40, As;
    mov.u64 %rd41, Bs;

    shl.b32 %r13, %r4, 7;         // ty*32 floats * 4 bytes
    shl.b32 %r14, %r3, 2;         // tx*4 bytes
    add.u32 %r15, %r13, %r14;     // shared store byte base for this thread

    cvt.u64.u32 %rd42, %r15;
    add.u64 %rd30, %rd40, %rd42;  // As[ty][tx]
    add.u64 %rd31, %rd30, 64;     // As[ty][tx+16]
    add.u64 %rd32, %rd30, 2048;   // As[ty+16][tx]
    add.u64 %rd33, %rd32, 64;     // As[ty+16][tx+16]
    add.u64 %rd34, %rd41, %rd42;  // Bs[ty][tx]
    add.u64 %rd35, %rd34, 64;
    add.u64 %rd36, %rd34, 2048;
    add.u64 %rd37, %rd36, 64;

    // Inner-loop shared bases: A rows advance by 4 bytes per k, B cols by 128 bytes per k.
    cvt.u64.u32 %rd43, %r13;
    add.u64 %rd44, %rd40, %rd43;  // &As[ty][0]
    add.u64 %rd45, %rd44, 2048;   // &As[ty+16][0]
    cvt.u64.u32 %rd46, %r14;
    add.u64 %rd47, %rd41, %rd46;  // &Bs[0][tx]
    add.u64 %rd48, %rd47, 64;     // &Bs[0][tx+16]

    mov.u32 %r8, %r2;             // kt = by; if by>bx loop is skipped and zeros are stored
kt_loop:
    setp.gt.u32 %p0, %r8, %r1;
    @%p0 bra kt_done;

    shl.b32 %r7, %r8, 5;          // k0 = kt*32

    // Load A tile: rows r9/r10, cols k0+tx / k0+tx+16.
    add.u32 %r21, %r7, %r3;
    add.u32 %r22, %r21, 16;

    mad.lo.u32 %r23, %r9, %r0, %r21;
    shl.b32 %r23, %r23, 2;
    cvt.u64.u32 %rd50, %r23;
    add.u64 %rd50, %rd0, %rd50;
    ld.global.nc.f32 %f10, [%rd50];
    st.shared.f32 [%rd30], %f10;

    mad.lo.u32 %r23, %r9, %r0, %r22;
    shl.b32 %r23, %r23, 2;
    cvt.u64.u32 %rd51, %r23;
    add.u64 %rd51, %rd0, %rd51;
    ld.global.nc.f32 %f11, [%rd51];
    st.shared.f32 [%rd31], %f11;

    mad.lo.u32 %r23, %r10, %r0, %r21;
    shl.b32 %r23, %r23, 2;
    cvt.u64.u32 %rd52, %r23;
    add.u64 %rd52, %rd0, %rd52;
    ld.global.nc.f32 %f12, [%rd52];
    st.shared.f32 [%rd32], %f12;

    mad.lo.u32 %r23, %r10, %r0, %r22;
    shl.b32 %r23, %r23, 2;
    cvt.u64.u32 %rd53, %r23;
    add.u64 %rd53, %rd0, %rd53;
    ld.global.nc.f32 %f13, [%rd53];
    st.shared.f32 [%rd33], %f13;

    // Load B tile: rows k0+ty / k0+ty+16, cols r11/r12.
    add.u32 %r24, %r7, %r4;
    add.u32 %r25, %r24, 16;

    mad.lo.u32 %r23, %r24, %r0, %r11;
    shl.b32 %r23, %r23, 2;
    cvt.u64.u32 %rd54, %r23;
    add.u64 %rd54, %rd1, %rd54;
    ld.global.nc.f32 %f14, [%rd54];
    st.shared.f32 [%rd34], %f14;

    mad.lo.u32 %r23, %r24, %r0, %r12;
    shl.b32 %r23, %r23, 2;
    cvt.u64.u32 %rd55, %r23;
    add.u64 %rd55, %rd1, %rd55;
    ld.global.nc.f32 %f15, [%rd55];
    st.shared.f32 [%rd35], %f15;

    mad.lo.u32 %r23, %r25, %r0, %r11;
    shl.b32 %r23, %r23, 2;
    cvt.u64.u32 %rd56, %r23;
    add.u64 %rd56, %rd1, %rd56;
    ld.global.nc.f32 %f16, [%rd56];
    st.shared.f32 [%rd36], %f16;

    mad.lo.u32 %r23, %r25, %r0, %r12;
    shl.b32 %r23, %r23, 2;
    cvt.u64.u32 %rd57, %r23;
    add.u64 %rd57, %rd1, %rd57;
    ld.global.nc.f32 %f17, [%rd57];
    st.shared.f32 [%rd37], %f17;

    bar.sync 0;

    mov.u32 %r26, 0;              // kk
kk_loop:
    setp.ge.u32 %p1, %r26, 32;
    @%p1 bra kk_done;

    shl.b32 %r27, %r26, 2;        // kk*4
    shl.b32 %r28, %r26, 7;        // kk*128

    cvt.u64.u32 %rd58, %r27;
    add.u64 %rd60, %rd44, %rd58;  // &As[ty][kk]
    add.u64 %rd61, %rd45, %rd58;  // &As[ty+16][kk]
    cvt.u64.u32 %rd59, %r28;
    add.u64 %rd62, %rd47, %rd59;  // &Bs[kk][tx]
    add.u64 %rd63, %rd48, %rd59;  // &Bs[kk][tx+16]

    ld.shared.f32 %f10, [%rd60];
    ld.shared.f32 %f11, [%rd61];
    ld.shared.f32 %f12, [%rd62];
    ld.shared.f32 %f13, [%rd63];

    fma.rn.f32 %f0, %f10, %f12, %f0;
    fma.rn.f32 %f1, %f10, %f13, %f1;
    fma.rn.f32 %f2, %f11, %f12, %f2;
    fma.rn.f32 %f3, %f11, %f13, %f3;

    add.u32 %r26, %r26, 1;
    bra kk_loop;
kk_done:

    bar.sync 0;
    add.u32 %r8, %r8, 1;
    bra kt_loop;
kt_done:

    // Store a 2x2 micro tile. row>col locations are written as zero, so the
    // strictly lower triangle is explicitly produced rather than left stale.
    add.u32 %r31, %r5, %r4;       // C row 0
    add.u32 %r32, %r31, 16;       // C row 1

    setp.le.u32 %p2, %r31, %r11;
    setp.lt.u32 %p3, %r31, %r0;
    setp.lt.u32 %p4, %r11, %r0;
    and.pred %p5, %p3, %p4;
    selp.f32 %f20, %f0, %f30, %p2;
    mad.lo.u32 %r33, %r31, %r0, %r11;
    shl.b32 %r33, %r33, 2;
    cvt.u64.u32 %rd70, %r33;
    add.u64 %rd70, %rd2, %rd70;
    @%p5 st.global.f32 [%rd70], %f20;

    setp.le.u32 %p6, %r31, %r12;
    setp.lt.u32 %p7, %r12, %r0;
    and.pred %p8, %p3, %p7;
    selp.f32 %f21, %f1, %f30, %p6;
    mad.lo.u32 %r34, %r31, %r0, %r12;
    shl.b32 %r34, %r34, 2;
    cvt.u64.u32 %rd71, %r34;
    add.u64 %rd71, %rd2, %rd71;
    @%p8 st.global.f32 [%rd71], %f21;

    setp.le.u32 %p9, %r32, %r11;
    setp.lt.u32 %p10, %r32, %r0;
    and.pred %p11, %p10, %p4;
    selp.f32 %f22, %f2, %f30, %p9;
    mad.lo.u32 %r35, %r32, %r0, %r11;
    shl.b32 %r35, %r35, 2;
    cvt.u64.u32 %rd72, %r35;
    add.u64 %rd72, %rd2, %rd72;
    @%p11 st.global.f32 [%rd72], %f22;

    setp.le.u32 %p12, %r32, %r12;
    and.pred %p13, %p10, %p7;
    selp.f32 %f23, %f3, %f30, %p12;
    mad.lo.u32 %r36, %r32, %r0, %r12;
    shl.b32 %r36, %r36, 2;
    cvt.u64.u32 %rd73, %r36;
    add.u64 %rd73, %rd2, %rd73;
    @%p13 st.global.f32 [%rd73], %f23;

    ret;
}

"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("triu_matmul_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A, B):
        n = A.shape[0]
        C = torch.empty((n, n), dtype=A.dtype, device=A.device)
        module = _get_ptx_module()
        module.launch(
            "triu_matmul_kernel",
            grid=(n // 32, n // 32, 1),
            block=(16, 16, 1),
            arguments=[A, B, C, i32(n)],
            shared_memory=8192,
            stream=torch.cuda.current_stream(A.device),
        )
        return C

